cat /app/resources/treasury_bulletin_1988_03.json | python3 -c "
import json,sys
d = json.load(sys.stdin)
# Get elements and look for tables
pages = d['document'].get('pages', [])
for i, page in enumerate(pages[:10]):
    elements = page.get('elements', [])
    for el in elements:
        if el.get('type') == 'table':
            print(f'Page {i}: Found table with {len(el.get(\"rows\", []))} rows')
        if el.get('type') == 'text':
            text = el.get('text', '')[:100]
            if '2-year' in text:
                print(f'Page {i} text: {text[:150]}...')
"
